// 页面渲染服务：根据用户提交的模板片段动态渲染公告页
const express = require('express');
const ejs = require('ejs');
const app = express();
app.use(express.urlencoded({ extended: false }));

// 渲染入口：POST /render，请求体中的 template 字段即页面模板源码
app.post('/render', (req, res) => {
  const userTemplate = req.body.template; // 用户输入直接作为模板源码
  if (!userTemplate) {
    return res.status(400).send('missing template');
  }
  try {
    // ejs.render 首参是模板源码：先编译为函数再执行，<%= %> 内表达式会被求值
    const html = ejs.render(userTemplate, { title: '公告', version: '1.0' });
    res.type('html').send(html);
  } catch (err) {
    res.status(500).send('render failed');
  }
});

app.listen(3000, () => console.log('render service on 3000'));
```

