// 营销落地页生成器：运营人员通过接口提交自定义活动模板，服务端渲染后发布
const nunjucks = require('nunjucks');
const express = require('express');
const app = express();
app.use(express.json());

const pages = {}; // 已发布落地页缓存：id -> html

// 外部输入入口：POST /api/landing-page/create 的 body.template 即模板源码
app.post('/api/landing-page/create', (req, res) => {
  const userStr = req.body.template; // 攻击者完全可控的模板字符串
  if (typeof userStr !== 'string' || userStr.length > 5000) {
    return res.status(400).json({ error: 'invalid template' });
  }
  // 危险点：userStr 被直接编译为模板并渲染，{{7*7}} 会被求值为 49
  const html = nunjucks.renderString(userStr, { brand: 'Acme', year: 2024 });
  const id = 'page_' + Date.now();
  pages[id] = html;
  res.json({ id, preview: html });
});

// 访问已发布落地页
app.get('/api/landing-page/:id', (req, res) => {
  res.type('html').send(pages[req.params.id] || 'not found');
});

app.listen(3000);
```

