import freemarker.template.Configuration;
import freemarker.template.Template;
import org.springframework.web.bind.annotation.*;

import java.io.StringReader;
import java.io.StringWriter;
import java.util.HashMap;
import java.util.Map;

// 通知中心：运营后台支持自定义通知正文模板并实时预览
@RestController
@RequestMapping("/notify")
public class NotificationTemplateController {

    private final Configuration cfg = new Configuration(Configuration.VERSION_2_3_31);
    // 未调用 cfg.setNewBuiltinClassResolver(TemplateClassResolver.SAFER_RESOLVER)，?new 默认可实例化任意类

    // 前端表单直接提交模板文本（本意是自定义问候语）
    @PostMapping("/preview")
    public String preview(@RequestParam("tpl") String userTpl) throws Exception {
        // 危险：用户输入被直接当作模板源码交给 FreeMarker 编译
        Template template = new Template("t", new StringReader(userTpl), cfg);

        StringWriter out = new StringWriter();
        // process 阶段执行模板指令，攻击者可注入 <#assign ex='freemarker.template.utility.Execute'?new()>${ex('id')}
        template.process(new HashMap<String, Object>(), out);
        return out.toString();   // 渲染结果原样返回前端
    }
}
```

