<?php
// doc_render.php —— 文档渲染服务：用户自定义公告正文模板片段，服务端渲染输出
require_once __DIR__ . '/vendor/autoload.php';

use Twig\Environment;
use Twig\Loader\ArrayLoader;

function renderDocument(string $userTpl, array $docMeta): string
{
    $loader = new ArrayLoader(['layout.html' => '【{{ title }}】']);
    // 仅开启 autoescape；未加载 SandboxExtension，模板拥有完整语法能力
    $env = new Environment($loader, ['autoescape' => true]);

    // 用户字符串被直接作为模板源码编译（危险入口）
    $tpl = $env->createTemplate($userTpl);
    return $tpl->render(['title' => $docMeta['title']]);
}

// HTTP 入口：POST 的 body 字段即模板源码，title 为文档元数据
$userTpl = $_POST['body'] ?? '{{ title }} 默认正文';
$docMeta = ['title' => $_POST['title'] ?? '未命名文档'];

header('Content-Type: text/html; charset=utf-8');
echo renderDocument($userTpl, $docMeta);
```

