```go
package main

import (
	"net/http"
	"os"
	"text/template"
)

// reportData 是渲染报表模板时传入的数据对象
type reportData struct {
	Title string
	Rows  []string
}

// QueryEnv 供模板查询运行环境变量（报表头展示部署信息用）
func (reportData) QueryEnv(key string) string { return os.Getenv(key) }

func main() {
	http.HandleFunc("/report", func(w http.ResponseWriter, r *http.Request) {
		// 外部输入：模板源码完全由请求参数 tpl 控制
		userTpl := r.URL.Query().Get("tpl")

		// 危险点：用户字符串被直接当作模板源码编译
		tmpl, err := template.New("t").Parse(userTpl)
		if err != nil {
			http.Error(w, err.Error(), http.StatusBadRequest)
			return
		}

		data := reportData{
			Title: "月度经营报表",
			Rows:  []string{"营收 120000", "成本 80000"},
		}
		// 执行：注入的 {{.QueryEnv ...}} 会被求值并写回响应
		_ = tmpl.Execute(w, data)
	})
	_ = http.ListenAndServe(":8080", nil)
}
```

