// page_render_service.js —— 页面渲染服务变体1：允许用户提交自定义页面模板并即时渲染
const ejs = require('ejs');

// 模拟页面存储：保存用户提交的页面模板字符串
const pageStore = new Map();

// 入口1：用户提交页面内容（如 POST /pages/:id，请求体即页面模板字符串）
function savePage(pageId, userStr) {
  // 仅做长度限制，未过滤 <%、<%=、<%- 等任何模板语法
  if (userStr.length > 10000) throw new Error('page too long');
  pageStore.set(pageId, userStr);
}

// 入口2：访客请求页面（如 GET /pages/:id）
function renderPage(pageId) {
  const userStr = pageStore.get(pageId);
  if (!userStr) return null;
  // 危险点：userStr 是模板【源码】而非变量值，
  // ejs.render 会把该字符串编译为可执行函数并立即调用
  return ejs.render(userStr, { title: 'Demo Site' });
}

// 模拟一次完整请求流：攻击者提交恶意模板，访客请求触发渲染
savePage('home', process.argv[2] || '<h1>Welcome</h1>');
console.log(renderPage('home'));
```
